--
-- Table structure for table `OperatingStop`
--

DROP TABLE IF EXISTS `OperatingStop`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `OperatingStop` (
  `stop_id` int NOT NULL AUTO_INCREMENT,
  `vendor_id` int NOT NULL,
  `location_id` int NOT NULL,
  `scheduled_start` datetime NOT NULL,
  `scheduled_end` datetime NOT NULL,
  `actual_start` datetime DEFAULT NULL,
  `actual_end` datetime DEFAULT NULL,
  `stop_status` varchar(30) NOT NULL,
  `notes` text,
  PRIMARY KEY (`stop_id`),
  KEY `vendor_id` (`vendor_id`),
  KEY `location_id` (`location_id`),
  CONSTRAINT `OperatingStop_ibfk_1` FOREIGN KEY (`vendor_id`) REFERENCES `Vendor` (`vendor_id`),
  CONSTRAINT `OperatingStop_ibfk_2` FOREIGN KEY (`location_id`) REFERENCES `Location` (`location_id`),
  CONSTRAINT `chk_actual_order` CHECK (((`actual_end` is null) or ((`actual_start` is not null) and (`actual_end` > `actual_start`)))),
  CONSTRAINT `chk_sched_order` CHECK ((`scheduled_end` > `scheduled_start`))
) ENGINE=InnoDB AUTO_INCREMENT=327 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

