DROP TABLE IF EXISTS `Photo`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `Photo` (
  `photo_id` int NOT NULL AUTO_INCREMENT,
  `uploader_user_id` int NOT NULL,
  `vendor_id` int NOT NULL,
  `image_url` varchar(500) NOT NULL,
  `caption` varchar(255) DEFAULT NULL,
  `uploaded_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`photo_id`),
  KEY `uploader_user_id` (`uploader_user_id`),
  KEY `vendor_id` (`vendor_id`),
  CONSTRAINT `Photo_ibfk_1` FOREIGN KEY (`uploader_user_id`) REFERENCES `User` (`user_id`),
  CONSTRAINT `Photo_ibfk_2` FOREIGN KEY (`vendor_id`) REFERENCES `Vendor` (`vendor_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1868 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
